#include <set>
#include <iostream>

int main() {
    std::set<int> coll = {1, 2, 3, 4, 5, 6};

    // Range erase: Removes [1, 3). '3' is the exclusive end.
    coll.erase(coll.begin(), coll.find(3)); 

    std::cout << *coll.begin() << "\n"; // Output: 3

    // Value erase (returns 1 for set)
    int num = coll.erase(5);
    std::cout << num << " element(s) removed by value\n"; // Output: 1

    // Example of multiset behavior (returns count > 1)
    std::multiset<int> m = {1, 1, 1};
    std::cout << m.erase(1) << " removed from multiset\n"; // Output: 3
}
